window.kbPageData["views/entry/k-d6c94fda4c1d006f"] = {"key":"entry/k-d6c94fda4c1d006f","state":{"route":"entry/k-d6c94fda4c1d006f"},"node":{"id":"k-d6c94fda4c1d006f","mode":"k","title":"都、鄙、邑（古汉语）","type":"概念与词义","domain":"汉语","reading":"","intro":"","priority":100,"aliases":["古汉语中都、鄙、邑的词义及其关系"],"qs":["国考 2025 行政执法 行测#90"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"“邑”指城镇。“都”本指大城邑，后引申为具有重要政治地位的大城邑。“鄙”指边邑，即边远的小城。","review":{"definition":"“邑”指城镇。“都”本指大城邑，后引申为具有重要政治地位的大城邑。“鄙”指边邑，即边远的小城。","explanation":"按题干给出的义项，“都”和“鄙”都属于“邑”，分别指大城邑和边远小城。D项用“邑”的大圈包住“都”和“鄙”两个互不相交的小圈，符合这一关系。A项把“邑”画在“都”里面，颠倒了包含关系。B项以“国”为外圈，但“国”可指诸侯封地或天子、诸侯的都城，题干未给出它涵盖所有“都”和“鄙”的依据。C项将三者画成彼此分离的圆，遗漏了“邑”对“都”和“鄙”的包含关系。","references":[],"evidence":"“都”指具有重要政治地位的大城邑，“邑”指城镇，“鄙”指边远的小城","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"国考 2025 行政执法 行测#90":{"paper":"国考 2025 行政执法 行测","n":90,"mod":"判断推理","src":["d8efe4e19862104d89c8.pdf",18],"asrc":["e2c4b1970d2b49eac0fd.pdf",28],"card":"7859b6358e8feba9108bc8c4","links":[{"id":"k-d6c94fda4c1d006f","role":"解题依据","why":"都和鄙分别指大城邑和边远小城，二者是邑所包含的并列类别。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-d6c94fda4c1d006f":[["国考 2025 行政执法 行测#90"]]}};
